BEGIN;
-- 1) 경쟁사 예시행 삭제
DELETE FROM competitors WHERE competitor_id IN ('CP001', 'CP002') AND note LIKE '예시행%';
-- 2) bm_mapping 전체 교체 (competitors에서 재집계한 93행)
DELETE FROM bm_mapping;
UPDATE bm_mapping SET created_at = now(), updated_at = now();
-- 3) MVP 템플릿 라이선스 문구
UPDATE mvp_strategy_templates
   SET description = replace(description, '무료 표준 설문', '표준 설문(상업적 사용 시 유료·허가 필요)'), updated_at = now()
 WHERE template_id IN ('mvp_sleep_easy_1', 'mvp_sleep_hard_1') AND description LIKE '%무료 표준 설문%';
-- 4) gate_matrix 활성 버전의 기기연동 2행 삭제
DELETE FROM gate_matrix m USING rule_versions v
 WHERE v.rule_version_id = m.rule_version_id AND v.status = 'active' AND m.acquire_method = '기기연동';
-- 5) 기대한 상태가 아니면 전체 롤백
DO $$
DECLARE c int; b int; e int; f int; g int; d int; o int;
BEGIN
  SELECT count(*) INTO c FROM competitors;
  SELECT count(*) INTO e FROM competitors WHERE note LIKE '예시행%';
  SELECT count(*) INTO b FROM bm_mapping;
  SELECT count(*) INTO f FROM mvp_strategy_templates WHERE description LIKE '%무료 표준 설문%';
  SELECT count(*) INTO g FROM gate_matrix m JOIN rule_versions v USING (rule_version_id) WHERE v.status = 'active';
  SELECT count(*) INTO d FROM gate_matrix m JOIN rule_versions v USING (rule_version_id) WHERE v.status = 'active' AND m.acquire_method IS NOT NULL;
  SELECT count(*) INTO o FROM bm_mapping bm, regexp_split_to_table(bm.contributing_competitor_ids, ',') x(id)
   WHERE NOT EXISTS (SELECT 1 FROM competitors cc WHERE cc.competitor_id = x.id);
  IF c <> 99 OR e <> 0 OR b <> 93 OR f <> 0 OR g <> 6 OR d <> 0 OR o <> 0 THEN
    RAISE EXCEPTION 'unexpected state: competitors=% examples=% bm=% mvp_free=% gate_active=% gate_device=% orphan_refs=%', c, e, b, f, g, d, o;
  END IF;
END $$;
COMMIT;
